use echode_actions::{Command, Session};
use echode_model::{Project, NoteDraft, Tick, Content, Note};
use std::hint::black_box;
use std::time::Instant;

fn fresh() -> (Project, echode_model::Id, echode_model::Id) {
    let (project, track) = Project::new().add_track("audit");
    let (project, _) = project.insert_note(track, NoteDraft { start: Tick::new(0), length: Tick::new(1), pitch: 60, velocity: 100 }).unwrap();
    let clip = project.tracks()[0].clips[0].id;
    (project, track, clip)
}

fn boundaries() {
    let (project, track, clip) = fresh();
    let resized = project.resize_clip(track, clip, Tick::new(i64::MIN), Tick::new(1)).unwrap();
    let linked = resized.link_clip(clip, track, Tick::new(0), echode_model::Id::generate()).unwrap();
    println!("linked_origin_overflow={:?}", linked.check_invariants());
    let mut session = Session::open(resized);
    let applied = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| session.perform(Command::LinkClip { source: clip, track, start: Tick::new(0) })));
    println!("session_link_origin_overflow={applied:?}");

    let (project, track, clip) = fresh();
    let resized = project.resize_clip(track, clip, Tick::new(i64::MAX - 1), Tick::new(1)).unwrap();
    let linked = resized.link_clip(clip, track, Tick::new(0), echode_model::Id::generate()).unwrap();
    println!("pre_insert={:?}", linked.check_invariants());
    let inserted = linked.insert_note(track, NoteDraft { start: Tick::new(0), length: Tick::new(2), pitch: 61, velocity: 100 }).unwrap().0;
    println!("inserted_content_end_overflow={:?}", inserted.check_invariants());

    let (project, _, _) = fresh();
    let mut track = (*project.tracks()[0]).clone();
    let content_id = track.clips[0].content;
    track.clips[0].length = Tick::new(1);
    let content = Content { id: content_id, audio: None, takes: vec![], expressions: vec![], notes: vec![Note {
        id: echode_model::Id::generate(), start: Tick::new(i64::MIN + 1), length: Tick::new(1), pitch: 60, velocity: 100, release: 0, articulation: None,
    }] };
    let assembled = std::panic::catch_unwind(|| Project::try_assemble(project.meter(), project.tempo().clone(), vec![content], vec![track]));
    println!("extreme_assembly={assembled:?}");
}

fn clones() {
    let (project, _) = Project::new().add_track("one track");
    let parameter = project.tracks()[0].devices[0].parameters[0].id;
    let mut session = Session::open(project);
    let mut previous = 0;
    for target in [100, 1000, 10000, 50000] {
        for i in previous..target {
            session.perform(Command::SetParameter { parameter, value: if i % 2 == 0 {0.5} else {1.0} }).unwrap();
        }
        let mut timings = Vec::new();
        for _ in 0..7 {
            let start = Instant::now();
            let before = black_box(session.clone());
            let copied = start.elapsed();
            drop(before);
            timings.push(copied.as_secs_f64() * 1000.0);
        }
        timings.sort_by(f64::total_cmp);
        println!("session_clone edits={target} median_ms={:.6} journal_entries={}", timings[3], session.journal().len());
        previous = target;
    }
}

fn full_note_diff() {
    for count in [1000, 10000, 100000] {
        let (base, _, _) = fresh();
        let mut track = (*base.tracks()[0]).clone();
        track.clips[0].kind = echode_model::ClipKind::Fixed;
        let mut content = (*base.contents()[0]).clone();
        content.notes = (0..count).map(|i| Note { id: echode_model::Id::from_raw((i + 1) as u128), start: Tick::new(i), length: Tick::new(1), pitch: 60, velocity: 100, release: 0, articulation: None }).collect();
        let project = Project::try_assemble(base.meter(), base.tempo().clone(), vec![content], vec![track]).unwrap();
        let parameter = project.tracks()[0].devices[0].parameters[0].id;
        let after = project.set_parameter(parameter, 0.5).unwrap();
        let mut timings = Vec::new();
        for _ in 0..7 {
            let start = Instant::now();
            black_box(project.diff(&after));
            timings.push(start.elapsed().as_secs_f64() * 1000.0);
        }
        timings.sort_by(f64::total_cmp);
        println!("gain_diff notes={count} median_ms={:.6}", timings[3]);
    }
}

fn clone_note_history() {
    let (project, track) = Project::new().add_track("notes");
    let mut session = Session::open(project);
    let mut previous = 0;
    for count in [500, 1000, 2000, 4000] {
        for i in previous..count {
            session.perform(Command::InsertNote { track, draft: NoteDraft { start: Tick::new(i), length: Tick::new(1), pitch: 60, velocity: 100 } }).unwrap();
        }
        let mut timings = Vec::new();
        for _ in 0..5 {
            let start = Instant::now();
            let before = black_box(session.clone());
            let copied = start.elapsed();
            drop(before);
            timings.push(copied.as_secs_f64() * 1000.0);
        }
        timings.sort_by(f64::total_cmp);
        println!("session_clone_insert_history notes={count} median_ms={:.6}", timings[2]);
        previous = count;
    }
}

fn main() {
    boundaries();
    if std::env::args().any(|arg| arg == "boundaries") { return; }
    clones();
    full_note_diff();
    clone_note_history();
}

