use echode_draw::{ArrangeIndex, ArrangeView};
use echode_model::{ClipKind, Content, Id, Lane, Meter, Note, Placement, Project, Tempo, TempoMap, Tick, Track, initial_order, test_mixer};
use fractional_index::FractionalIndex;
use std::hint::black_box;
use std::time::Instant;

fn assemble(contents: Vec<Content>, tracks: Vec<Track>) -> Project {
    Project::try_assemble(Meter::four_four(), TempoMap::new(Tempo::quarters_per_minute(120).unwrap()), contents, tracks).unwrap()
}
fn clip(id: u128, content: u128, start: i64, length: i64) -> Placement {
    Placement { id: Id::from_raw(id), content: Id::from_raw(content), lane: Lane::Timeline,
        start: Tick::new(start), length: Tick::new(length), offset: Tick::new(0), kind: ClipKind::Fixed,
        gain: 1., fade_in: 0, fade_out: 0 }
}
fn content(id: u128, notes: Vec<Note>) -> Content {
    Content { id: Id::from_raw(id), audio: None, takes: vec![], notes, expressions: vec![] }
}
fn note(id: u128, start: i64) -> Note {
    Note { id: Id::from_raw(id), start: Tick::new(start), length: Tick::new(1), pitch: 60, velocity: 50_000, release: 0, articulation: None }
}
fn measure(mut action: impl FnMut(), runs: usize) -> f64 {
    for _ in 0..4 { action(); }
    let mut timings = (0..7).map(|_| { let at=Instant::now(); for _ in 0..runs { action(); } at.elapsed().as_secs_f64() * 1e6 / runs as f64 }).collect::<Vec<_>>();
    timings.sort_by(f64::total_cmp); timings[3]
}
fn main() {
    println!("{{\"arrange\":[");
    for (case,n) in [1, 1000, 10_000, 100_000].into_iter().enumerate() {
        let contents = (0..n).map(|i|content(1_000_000_000+i as u128, vec![note(2_000_000_000+i as u128,0)])).collect();
        let clips = (0..n).map(|i|clip(3_000_000_000+i as u128,1_000_000_000+i as u128,i as i64*2,1)).collect();
        let project = assemble(contents,vec![Track{id:Id::from_raw(1),name:"visible".into(),parent:None,order:initial_order(),clips,devices:vec![test_mixer(1)]}]);
        let index = ArrangeIndex::build(&project);
        let view = ArrangeView{origin_tick:Tick::new((n as i64-1)*2),width_ticks:1,origin_track:0.,height_tracks:1.,pixels_per_tick:20.,pixels_per_track:64.};
        let mut hits=0;
        let us=measure(||{hits=0;index.visit_visible(black_box(&project),black_box(view),|e|{black_box(e);hits+=1;});black_box(hits);},100);
        println!("{}{{\"contents\":{n},\"hits\":{hits},\"microseconds\":{us}}}",if case==0{""}else{","});
    }
    println!("],\"piano_lookup\":[");
    for (case,n) in [1,1000,10_000,100_000].into_iter().enumerate() {
        let notes=(0..n).map(|i|note(1_000_000+i as u128,i as i64*2)).collect();
        let project=assemble(vec![content(1000,notes)],vec![Track{id:Id::from_raw(1),name:"notes".into(),parent:None,order:initial_order(),clips:vec![clip(2000,1000,0,n as i64*2)],devices:vec![test_mixer(1)]}]);
        let index=ArrangeIndex::build(&project);
        let us=measure(||{black_box(index.piano_note(black_box(&project),Id::from_raw(1),Some(Id::from_raw(2000)),Id::from_raw(1_000_000)));},100);
        println!("{}{{\"notes\":{n},\"microseconds\":{us}}}",if case==0{""}else{","});
    }
    println!("],\"index_update\":[");
    for (case,n) in [100,1000,5000,10_000].into_iter().enumerate() {
        let mut key=FractionalIndex::default();
        let tracks=(0..n).map(|i| {let order=key.to_string();key=FractionalIndex::new_after(&key);Track{id:Id::from_raw(100+i as u128),name:"track".into(),parent:None,order,clips:vec![],devices:vec![test_mixer(100+i as u128)]}}).collect();
        let project=assemble(vec![],tracks);let index=ArrangeIndex::build(&project);
        let us=measure(||{black_box(index.update(black_box(&project)));},1);
        println!("{}{{\"tracks\":{n},\"microseconds\":{us}}}",if case==0{""}else{","});
    }
    println!("]}}");
}

