#include "echode.h"
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

static void callback(void *context, int status, const char *message, struct Snapshot *snapshot) {
    fprintf(stderr, "callback status=%d, calling shutdown from the document worker\n", status);
    if (snapshot) echode_snapshot_free(snapshot);
    echode_document_shutdown((struct Document *)context);
    fprintf(stderr, "shutdown returned\n");
    _exit(0);
}

int main(int argc, char **argv) {
    if (argc != 2) return 2;
    struct Document *document = echode_document_create(argv[1]);
    if (!document) return 3;
    echode_document_query(document, ECHODE_DOCUMENT_SNAPSHOT, document, callback);
    for (int i = 0; i < 500; i++) usleep(10000);
    fprintf(stderr, "callback did not finish\n");
    return 4;
}
